"""Daily stock count and reorder check for TableLite."""

def record_count(counts, item, qty):
    counts[item] = qty
    return counts

def reorder_list(counts, par_levels):
    return [i for i, par in par_levels.items() if counts.get(i, 0) < par]

if __name__ == "__main__":
    par = {"tortillas": 100, "horchata mix": 2}
    c = record_count({}, "tortillas", 40)
    print("Reorder:", reorder_list(c, par))
EOF
